\centering
\includegraphics[width=\linewidth]{mxfp4_gdn_datapath_paper_fit.png}
\caption{Overview of the proposed native MXFP4 persistent-state Gated DeltaNet decode datapath. Token inputs are packed into MXFP4 blocks, the recurrent state remains resident in on-chip BRAM/URAM, and native E2M1 LUT multiplication with block-scale alignment and fixed-point accumulation is reused across prediction, state update, and output generation.}
\label{fig:mxfp4_gdn_datapath}
\end{figure}

