\begin{table}[t]
\centering
\caption{Arithmetic formats used in the proposed datapath.}
\label{tab:data_formats}
\footnotesize
\renewcommand{\arraystretch}{1.0}
\setlength{\tabcolsep}{6pt}
\begin{tabularx}{\linewidth}{llX}
\toprule
Tensor / Value & Format & Notes \\
\midrule
Weights & MXFP4 & Block size 32 \\
Activations & MXFP4 & Dynamic per token \\
Recurrent state & MXFP4 & Stored on chip \\
Beta & INT8 & Scaling parameter \\
Partial products & Q4.3 & From E2M1 multiply \\
Accumulator & INT24 & Block-aligned accumulation \\
Final output & FP16 & Output format \\
\bottomrule
\end{tabularx}
\end{table}

