\setlength{\tabcolsep}{6pt}
\begin{tabularx}{\linewidth}{Xcc}
\toprule
Design & Latency ($\mu$s/token) & Speedup vs. H100 \\
\midrule
H100 baseline & 285.0 & 1.00$\times$ \\
FPGA baseline & 63.2 & 4.51$\times$ \\
Ours MXFP4 & 51.472 & 5.54$\times$ \\
\bottomrule
\end{tabularx}
\end{table}

